CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('USER','ADMIN');
CREATE TYPE document_role AS ENUM ('UNKNOWN','APPLICATION_ORIGINAL','OFFICE_ACTION','RESPONSE_STATEMENT','CLAIMS_CURRENT','CLAIMS_REPLACEMENT','CLAIMS_COMPARISON','PRIOR_ART','OTHER');
CREATE TYPE case_status AS ENUM ('INCOMPLETE','NEEDS_CONFIRMATION','READY','PROCESSING','COMPLETED','FAILED');
CREATE TYPE upload_status AS ENUM ('INIT','UPLOADING','UPLOADED','FAILED');
CREATE TYPE parse_status AS ENUM ('PENDING','PROCESSING','PARSED','FAILED');
CREATE TYPE run_status AS ENUM ('QUEUED','ANALYZING','DRAFTING','QUALITY_CHECK','GENERATING_DOCUMENT','COMPLETED','FAILED','QA_FAILED','CANCELLED');
CREATE TYPE step_status AS ENUM ('PENDING','RUNNING','SUCCEEDED','FAILED','SKIPPED');
CREATE TYPE worker_job_status AS ENUM ('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED');
CREATE TYPE worker_job_type AS ENUM ('PARSE_DOCUMENT','BUILD_DOCX','RENDER_DOCX');
CREATE TYPE artifact_type AS ENUM ('PARSED_MANIFEST','CASE_SNAPSHOT','ISSUE_LIST','EVIDENCE_MATRIX','STRATEGY_DECISION','AMENDMENT_PLAN','STATEMENT_JSON','QA_REPORT','STATEMENT_DOCX','RENDERED_PDF','PAGE_RENDER_ARCHIVE','RUN_TRACE');
CREATE TYPE qa_severity AS ENUM ('INFO','WARNING','ERROR','BLOCKER');
CREATE TYPE repair_status AS ENUM ('OPEN','AUTO_FIXED','MANUAL_FIXED','WAIVED');
CREATE TYPE skill_version_status AS ENUM ('DRAFT','STAGING','PUBLISHED','ARCHIVED');
CREATE TYPE model_purpose AS ENUM ('CLASSIFICATION','EXTRACTION','ANALYSIS','DRAFTING','QA','VISION_QA');
CREATE TYPE eval_run_status AS ENUM ('QUEUED','RUNNING','COMPLETED','FAILED');

CREATE TABLE app_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), identity_user_id text UNIQUE NOT NULL, email text NOT NULL, role user_role NOT NULL DEFAULT 'USER', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id uuid NOT NULL REFERENCES app_users(id), application_no text, title text, applicant text, internal_case_no text, status case_status NOT NULL DEFAULT 'INCOMPLETE', current_oa_document_id uuid, current_claim_version_id uuid, current_oa_confirmed boolean NOT NULL DEFAULT false, current_claims_confirmed boolean NOT NULL DEFAULT false, readiness_json jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE INDEX cases_owner_updated_idx ON cases(owner_user_id, updated_at DESC); CREATE INDEX cases_application_no_idx ON cases(application_no); CREATE INDEX cases_deleted_at_idx ON cases(deleted_at);
CREATE TABLE documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES cases(id) ON DELETE CASCADE, role document_role NOT NULL DEFAULT 'UNKNOWN', oa_round int CHECK (oa_round IS NULL OR oa_round >= 1), prior_art_label text CHECK (prior_art_label IS NULL OR prior_art_label ~ '^D[1-9][0-9]*$'), role_confidence numeric(4,3), user_confirmed boolean NOT NULL DEFAULT false, display_name text, ai_suggestion jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX documents_case_idx ON documents(case_id);
CREATE TABLE document_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES documents(id) ON DELETE CASCADE, version_no int NOT NULL, original_filename text NOT NULL, mime_type text NOT NULL, size_bytes bigint NOT NULL, sha256 text NOT NULL, storage_key text UNIQUE NOT NULL, upload_status upload_status NOT NULL DEFAULT 'INIT', parse_status parse_status NOT NULL DEFAULT 'PENDING', parse_error_code text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(document_id, version_no));
CREATE TABLE parsed_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_version_id uuid UNIQUE NOT NULL REFERENCES document_versions(id) ON DELETE CASCADE, parser_version text NOT NULL, page_count int, text_quality numeric(4,3), is_scanned boolean NOT NULL DEFAULT false, full_text_key text NOT NULL, manifest_key text NOT NULL, extracted_metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE case_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES cases(id) ON DELETE CASCADE, event_type text NOT NULL, event_date date, document_id uuid REFERENCES documents(id), source text NOT NULL, confidence numeric(4,3), data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE claim_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES cases(id) ON DELETE CASCADE, source_document_version_id uuid REFERENCES document_versions(id), ordinal int NOT NULL, label text, effective_date date, claims_json jsonb NOT NULL, confidence numeric(4,3) NOT NULL, is_current boolean NOT NULL DEFAULT false, evidence_json jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(case_id, ordinal));
CREATE UNIQUE INDEX claim_versions_one_current_uq ON claim_versions(case_id) WHERE is_current = true;
CREATE TABLE skills (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE skill_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), skill_id uuid NOT NULL REFERENCES skills(id) ON DELETE CASCADE, version text NOT NULL, status skill_version_status NOT NULL DEFAULT 'DRAFT', is_active boolean NOT NULL DEFAULT false, bundle_key text NOT NULL, bundle_sha256 text NOT NULL, runtime_manifest jsonb NOT NULL, changelog text, created_by uuid REFERENCES app_users(id), created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, UNIQUE(skill_id, version));
CREATE UNIQUE INDEX skill_versions_one_active_uq ON skill_versions(skill_id) WHERE is_active = true;
CREATE TABLE skill_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), skill_version_id uuid NOT NULL REFERENCES skill_versions(id) ON DELETE CASCADE, path text NOT NULL, asset_type text NOT NULL, storage_key text NOT NULL, sha256 text NOT NULL, is_runtime_text boolean NOT NULL DEFAULT false, is_executable boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(skill_version_id, path));
CREATE TABLE model_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, purpose model_purpose NOT NULL, provider text NOT NULL, model text NOT NULL, secret_ref text NOT NULL, temperature numeric(3,2), max_output_tokens int, enabled boolean NOT NULL DEFAULT true, config jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now(), CHECK (secret_ref IN ('OPENAI_PRIMARY','OPENAI_SECONDARY','DEEPSEEK','MOCK')));
CREATE TABLE runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES cases(id), created_by uuid NOT NULL REFERENCES app_users(id), status run_status NOT NULL DEFAULT 'QUEUED', current_oa_document_id uuid NOT NULL REFERENCES documents(id), current_claim_version_id uuid NOT NULL REFERENCES claim_versions(id), skill_version_id uuid NOT NULL REFERENCES skill_versions(id), parser_version text NOT NULL, builder_version text NOT NULL, app_git_sha text, parent_run_id uuid, started_at timestamptz, finished_at timestamptz, error_code text, user_message text, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE runs ADD CONSTRAINT runs_parent_fk FOREIGN KEY(parent_run_id) REFERENCES runs(id); CREATE INDEX runs_case_created_idx ON runs(case_id, created_at DESC);
CREATE TABLE run_inputs (run_id uuid NOT NULL REFERENCES runs(id) ON DELETE CASCADE, document_version_id uuid NOT NULL REFERENCES document_versions(id), input_role text NOT NULL, PRIMARY KEY(run_id, document_version_id));
CREATE TABLE run_model_snapshots (run_id uuid NOT NULL REFERENCES runs(id) ON DELETE CASCADE, purpose text NOT NULL, provider text NOT NULL, model text NOT NULL, secret_ref text NOT NULL, config jsonb NOT NULL, PRIMARY KEY(run_id, purpose));
CREATE TABLE artifacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid REFERENCES runs(id) ON DELETE CASCADE, document_version_id uuid REFERENCES document_versions(id) ON DELETE CASCADE, type artifact_type NOT NULL, storage_key text NOT NULL, mime_type text NOT NULL, sha256 text, size_bytes bigint, is_user_downloadable boolean NOT NULL DEFAULT false, metadata jsonb NOT NULL DEFAULT '{}', attempt int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(run_id, type, attempt));
CREATE TABLE run_steps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES runs(id) ON DELETE CASCADE, step_key text NOT NULL, status step_status NOT NULL DEFAULT 'PENDING', attempt int NOT NULL DEFAULT 0, input_hash text, output_artifact_id uuid REFERENCES artifacts(id), started_at timestamptz, finished_at timestamptz, error_code text, error_detail_key text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(run_id, step_key));
CREATE TABLE worker_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid REFERENCES runs(id), document_version_id uuid REFERENCES document_versions(id), job_type worker_job_type NOT NULL, status worker_job_status NOT NULL DEFAULT 'QUEUED', payload jsonb NOT NULL DEFAULT '{}', result jsonb, attempt int NOT NULL DEFAULT 0, locked_by text, locked_at timestamptz, error_code text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX worker_jobs_claim_idx ON worker_jobs(status, created_at); CREATE UNIQUE INDEX worker_jobs_active_parse_uq ON worker_jobs(document_version_id, job_type) WHERE status IN ('QUEUED','RUNNING') AND job_type = 'PARSE_DOCUMENT';
CREATE TABLE qa_findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES runs(id) ON DELETE CASCADE, severity qa_severity NOT NULL, code text NOT NULL, location text, message text NOT NULL, expected jsonb, actual jsonb, basis jsonb, repair_status repair_status NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE model_calls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES runs(id) ON DELETE CASCADE, step_key text NOT NULL, purpose text NOT NULL, provider text NOT NULL, model text NOT NULL, request_schema_version text NOT NULL, prompt_template_hash text NOT NULL, skill_bundle_hash text NOT NULL, input_hash text NOT NULL, started_at timestamptz NOT NULL, finished_at timestamptz, usage jsonb, response_artifact_key text);
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid REFERENCES app_users(id), action text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE eval_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text, created_by uuid REFERENCES app_users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE eval_case_inputs (eval_case_id uuid NOT NULL REFERENCES eval_cases(id) ON DELETE CASCADE, document_version_id uuid NOT NULL REFERENCES document_versions(id), input_role text NOT NULL, PRIMARY KEY(eval_case_id, document_version_id));
CREATE TABLE eval_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), eval_case_id uuid NOT NULL REFERENCES eval_cases(id), skill_version_id uuid NOT NULL REFERENCES skill_versions(id), status eval_run_status NOT NULL DEFAULT 'QUEUED', run_id uuid REFERENCES runs(id), created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE TABLE eval_metrics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), eval_run_id uuid NOT NULL REFERENCES eval_runs(id) ON DELETE CASCADE, metric text NOT NULL, value numeric NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(eval_run_id, metric));

ALTER TABLE cases ADD CONSTRAINT cases_current_oa_fk FOREIGN KEY(current_oa_document_id) REFERENCES documents(id);
ALTER TABLE cases ADD CONSTRAINT cases_current_claim_fk FOREIGN KEY(current_claim_version_id) REFERENCES claim_versions(id);
